GS_ADD([{"id":"a-ie-order","reg":"Europe","mk":"IE","mkt":"Ireland","auth":"Department of Justice","cat":"Licensing","date":"2026-02-04","v":"official","t":"Ireland signs order opening GRAI licence applications","d":"Applications for betting licences opened on 9 February.","b":["The justice minister signed the commencement order under the Gambling Regulation Act 2024 on 4 February. It let GRAI accept remote, in-person and intermediary betting licence applications from 9 February and started its enforcement and complaints functions. Applicants must show they are suitable, can fund the business and that their money is lawful."],"src":[["GRAI, 4 Feb 2026","https://www.grai.ie/news/minister-jim-ocallaghan-signs-commencement-order-paving-the-way-for-grai-to-open-for-remote-and-in-person-licensing-applications","o"]],"archive":true,"es":{"mkt":"Irlanda","auth":"Departamento de Justicia","t":"Irlanda firma la orden que abre las solicitudes de licencia ante la GRAI","d":"Las solicitudes de licencias de apuestas se abrieron el 9 de febrero.","b":["El ministro de Justicia firmó el 4 de febrero la orden de entrada en vigor prevista en la Gambling Regulation Act 2024. La orden permitió a la GRAI aceptar desde el 9 de febrero solicitudes de licencias de apuestas remotas, presenciales y de intermediarios, y puso en marcha sus funciones de control y de reclamaciones. Los solicitantes deben demostrar su idoneidad, su capacidad para financiar el negocio y el origen lícito de sus fondos."]},"ru":{"mkt":"Ирландия","auth":"Министерство юстиции","t":"Ирландия подписала распоряжение об открытии приема заявок на лицензии GRAI","d":"Прием заявок на лицензии на ставки открылся 9 февраля.","b":["Министр юстиции 4 февраля подписал распоряжение о вступлении в силу в соответствии с Законом о регулировании азартных игр 2024 года. Оно позволило GRAI с 9 февраля принимать заявки на лицензии на дистанционные ставки, ставки в наземных пунктах и посредничество в ставках, а также запустило функции регулятора по правоприменению и рассмотрению жалоб. Заявители должны доказать свою благонадежность, способность финансировать бизнес и законное происхождение средств."]}},{"id":"a-uk-ceo","reg":"Europe","mk":"GB","mkt":"Great Britain","auth":"Gambling Commission","cat":"Licensing","date":"2026-02-09","v":"official","t":"Gambling Commission chief executive announces departure","d":"The deputy chief executive became acting chief executive from May.","b":["The Gambling Commission's chief executive said on 9 February that he would leave on 30 April 2026 for a new role. The deputy chief executive became acting chief executive while an interim chief executive is recruited."],"src":[["Gambling Commission, 9 Feb 2026","https://www.gamblingcommission.gov.uk/news/article/gambling-commission-chief-executive-announces-departure","o"]],"archive":true,"es":{"mkt":"Gran Bretaña","auth":"Gambling Commission","t":"El consejero delegado de la Gambling Commission anuncia su salida","d":"El consejero delegado adjunto asumió el cargo en funciones desde mayo.","b":["El consejero delegado de la Gambling Commission anunció el 9 de febrero que dejaría el cargo el 30 de abril de 2026 para asumir un nuevo puesto. El consejero delegado adjunto pasó a ejercer el cargo en funciones mientras se selecciona a un consejero delegado interino."]},"ru":{"mkt":"Великобритания","auth":"Gambling Commission","t":"Глава Комиссии по азартным играм объявил об уходе","d":"С мая обязанности главы исполняет его заместитель.","b":["Глава Комиссии по азартным играм 9 февраля сообщил, что покинет пост 30 апреля 2026 года ради новой должности. Заместитель главы стал исполняющим обязанности главы на время поиска временного руководителя."]}},{"id":"a-dk-l127","reg":"Europe","mk":"DK","mkt":"Denmark","auth":"Ministry of Taxation","cat":"Advertising","date":"2026-02-25","v":"official","t":"Denmark tables gambling ad bill, which lapses with the election","d":"The bill would ban gambling ads from 10 minutes before to 10 minutes after sports events.","b":["The tax minister tabled bill L 127, which bans gambling ads from 10 minutes before a sports event until 10 minutes after it ends, and tightens rules on fines, retailer approval and the unregulated market. It had seven parties behind it. The general election called the next day caused the bill to lapse."],"src":[["Ministry of Taxation, 25 Feb 2026","https://svmn.dk/aktuelt/presse-nyheder/pressemeddelelser/nu-kommer-floejt-til-floejt-forbuddet-nyt-lovforslag-skal-begraense-spilreklamer-og-styrke-indsatsen-mod-spilafhaengighed","o"],["SiGMA","https://sigma.world/news/denmark-moves-to-restrict-gambling-advertising-bill-l-127/","p"]],"archive":true,"es":{"mkt":"Dinamarca","auth":"Ministerio de Fiscalidad","t":"Dinamarca presenta un proyecto de ley sobre publicidad del juego que decae con las elecciones","d":"El proyecto prohibiría los anuncios de juego desde 10 minutos antes hasta 10 minutos después de los eventos deportivos.","b":["El ministro de Fiscalidad presentó el proyecto de ley L 127, que prohíbe los anuncios de juego desde 10 minutos antes de un evento deportivo hasta 10 minutos después de su final, y endurece las normas sobre multas, autorización de puntos de venta y mercado no regulado. Contaba con el apoyo de siete partidos. La convocatoria de elecciones generales al día siguiente hizo decaer el proyecto."]},"ru":{"mkt":"Дания","auth":"Министерство налогообложения","t":"Дания внесла законопроект о рекламе азартных игр, он утратил силу из-за выборов","d":"Законопроект запрещал рекламу азартных игр за 10 минут до спортивного события и в течение 10 минут после него.","b":["Министр налогообложения внес законопроект L 127. Он запрещает рекламу азартных игр за 10 минут до начала спортивного события и до истечения 10 минут после его окончания. Документ также ужесточает правила о штрафах, допуске розничных точек и нелегальном рынке. Его поддержали семь партий. Всеобщие выборы, объявленные на следующий день, привели к тому, что законопроект утратил силу."]}},{"id":"a-no-134","reg":"Europe","mk":"NO","mkt":"Norway","auth":"Lotteritilsynet","cat":"Enforcement","date":"2026-02-19","v":"official","t":"Norway orders 134 more gambling sites blocked","d":"It is the third DNS blocking order. 238 sites are now blocked.","b":["Lotteritilsynet ordered internet providers to block 134 unlicensed gambling sites by DNS, with a deadline of 26 February. It is the third order under the Gambling Act, after 57 sites in March 2025 and 47 in June 2025."],"src":[["Lotteritilsynet, decision of 19 Feb 2026 (PDF)","https://lottstift.no/app/uploads/2026/02/25_00681-316-25_00681-308-Vedtak-med-palegg-om-DNS-blokkering-av-nettsteder-som-tilbyr-pengesp-1355429_1_1.pdf","o"]],"archive":true,"es":{"mkt":"Noruega","auth":"Lotteritilsynet","t":"Noruega ordena bloquear otros 134 sitios de juego","d":"Es la tercera orden de bloqueo por DNS. Ya hay 238 sitios bloqueados.","b":["Lotteritilsynet ordenó a los proveedores de internet bloquear por DNS 134 sitios de juego sin licencia, con plazo hasta el 26 de febrero. Es la tercera orden dictada bajo la Ley del Juego, tras las de 57 sitios en marzo de 2025 y 47 en junio de 2025."]},"ru":{"mkt":"Норвегия","auth":"Lotteritilsynet","t":"Норвегия распорядилась заблокировать еще 134 игорных сайта","d":"Это третье предписание о DNS-блокировке. Сейчас заблокировано 238 сайтов.","b":["Регулятор Lotteritilsynet обязал интернет-провайдеров заблокировать по DNS 134 нелицензированных игорных сайта до 26 февраля. Это третье предписание по Закону об азартных играх. Ранее блокировались 57 сайтов в марте 2025 года и 47 в июне 2025 года."]}},{"id":"a-eu-amla-cdd","reg":"Europe","mk":"EU","mkt":"European Union","auth":"AMLA","cat":"Payments & AML","date":"2026-02-27","v":"official","t":"AMLA consults on due diligence standards, with gambling included","d":"The Malta Gaming Authority urged licensees to respond. Feedback on the main drafts was due by 8 May.","b":["The EU Anti-Money Laundering Authority opened consultations on three draft technical standards. Two fall under the AML Regulation: one on customer due diligence, and one on how to identify business relationships, occasional and linked transactions, and lower thresholds. The third, under the sixth AML Directive, covers reporting of material weaknesses.","The Malta Gaming Authority told licensees on 27 February that the consultations cover the non-financial sector, which includes gaming. It asked online and land-based operators to send feedback to AMLA directly. Comments on the directive standard were due by 9 March 2026, and on the two regulation standards by 8 May 2026."],"src":[["MGA, 27 Feb 2026","https://www.mga.org.mt/mga-invites-licensees-to-participate-in-amla-public-consultations-on-draft-regulatory-technical-standards/","o"]],"archive":true,"es":{"mkt":"Unión Europea","auth":"AMLA","t":"La AMLA abre consultas públicas sobre normas de diligencia debida que incluyen el juego","d":"La Malta Gaming Authority pidió a sus titulares de licencia que participen. Los comentarios sobre los borradores principales debían enviarse antes del 8 de mayo.","b":["La Autoridad de Lucha contra el Blanqueo de Capitales de la UE abrió consultas públicas sobre tres proyectos de normas técnicas. Dos se enmarcan en el Reglamento PBC/AML: uno sobre diligencia debida y otro sobre cómo identificar relaciones de negocio, transacciones ocasionales y vinculadas, y umbrales inferiores. El tercero, bajo la sexta Directiva PBC/AML, trata la comunicación de deficiencias importantes.","La Malta Gaming Authority comunicó a sus titulares de licencia el 27 de febrero que las consultas abarcan el sector no financiero, que incluye el juego. Pidió a los operadores online y presenciales que enviaran sus comentarios directamente a la AMLA. Los comentarios sobre la norma de la directiva debían presentarse antes del 9 de marzo de 2026, y los de las dos normas del reglamento antes del 8 de mayo de 2026."]},"ru":{"mkt":"Европейский союз","auth":"AMLA","t":"AMLA вынесло на общественное обсуждение стандарты проверки клиентов, включая азартные игры","d":"Мальтийское управление по азартным играм призвало лицензиатов направить отзывы. Замечания по основным проектам принимались до 8 мая.","b":["Европейское управление по противодействию отмыванию денег (AMLA) открыло общественное обсуждение трех проектов технических стандартов. Два из них относятся к Регламенту ПОД/ФТ (противодействие отмыванию доходов): один касается надлежащей проверки клиентов, другой описывает, как определять деловые отношения, разовые и связанные операции и пониженные пороги. Третий, по шестой директиве ПОД/ФТ, касается отчетности о существенных недостатках.","Мальтийское управление по азартным играм (MGA) 27 февраля сообщило лицензиатам, что обсуждение охватывает нефинансовый сектор, в том числе игорный. Оно попросило онлайн- и наземных операторов направлять отзывы напрямую в AMLA. Замечания по стандарту к директиве принимались до 9 марта 2026 года, по двум стандартам к регламенту до 8 мая 2026 года."]}},{"id":"a-ru-credit","reg":"Europe","mk":"RU","mkt":"Russia","auth":"State Duma","cat":"Payments & AML","date":"2026-02-17","v":"official","t":"Russia bill to ban betting with credit cards passes first reading","d":"The State Duma backed bill No. 720112-8 by 389 votes to none on 17 February.","b":["The State Duma passed bill No. 720112-8 in first reading on 17 February 2026, with 389 votes for, none against and no abstentions. The bill amends the gambling regulation law to ban bets made with borrowed money.","Under the bill, a bank that issued a credit card must refuse a payment for gambling when the payment system flags the transaction as such. The sponsoring senator told the chamber that the government and the presidential administration support the bill but have remarks to be dealt with before second reading."],"src":[["State Duma, plenary transcript 17 Feb 2026","http://api.duma.gov.ru/api/transcriptFull/2026-02-17","o"],["SiGMA","https://sigma.world/news/russia-wants-ban-betting-credit-cards/","p"]],"archive":true,"es":{"mkt":"Rusia","auth":"Duma Estatal","t":"El proyecto de ley ruso que prohíbe apostar con tarjeta de crédito supera la primera lectura","d":"La Duma Estatal respaldó el proyecto de ley n.º 720112-8 por 389 votos a favor y ninguno en contra el 17 de febrero.","b":["La Duma Estatal aprobó en primera lectura el proyecto de ley n.º 720112-8 el 17 de febrero de 2026, con 389 votos a favor, ninguno en contra y ninguna abstención. El proyecto modifica la ley de regulación del juego para prohibir las apuestas realizadas con dinero prestado.","Según el proyecto, el banco emisor de una tarjeta de crédito debe rechazar un pago de juego cuando el sistema de pago marque la operación como tal. El senador promotor dijo ante la cámara que el Gobierno y la Administración presidencial apoyan el proyecto, pero tienen observaciones que deberán resolverse antes de la segunda lectura."]},"ru":{"mkt":"Россия","auth":"Государственная дума","t":"Госдума приняла в первом чтении законопроект о запрете ставок с кредитных карт","d":"Государственная дума 17 февраля поддержала законопроект № 720112-8: 389 голосов за при отсутствии голосов против.","b":["Государственная дума приняла законопроект № 720112-8 в первом чтении 17 февраля 2026 года: 389 голосов за, против и воздержавшихся нет. Законопроект вносит изменения в закон о регулировании азартных игр и запрещает ставки за счет заемных средств.","Согласно законопроекту, банк, выпустивший кредитную карту, должен отказать в платеже за участие в азартных играх, если платежная система помечает операцию как таковую. Сенатор, внесший законопроект, сообщил палате, что правительство и администрация президента поддерживают документ, но имеют замечания, которые нужно учесть ко второму чтению."]}},{"id":"a-it-delay","reg":"Europe","mk":"IT","mkt":"Italy","auth":"ADM","cat":"Technology","date":"2026-02-27","v":"official","t":"ADM moves the new online gaming system deadline to 13 November","d":"ADM said very few certification requests had been filed by 23 February. Several player protection duties still apply from 13 May.","b":["In a letter of 27 February 2026 to online concessionaires, ADM's gaming directorate extended the deadline to complete conformity checks with verification bodies and get ADM's certificate for the new concessionaire system. The new date is 13 November 2026, instead of 13 May, and ADM called it final.","ADM said that by 23 February very few requests had reached verification bodies, and that checks with those bodies confirmed the original date could not be met. The delay covers only the technical certification steps.","Duties already in force stay in place, including a .it site owned by the concessionaire, ID and tax code checks at sign-up, limits for accounts opened after 13 November 2025 and the new self-exclusion rules. From 13 May concessionaires must also apply most responsible gaming measures in the concession agreement, and report cash top-ups at retail points so ADM can enforce the €100 weekly cap."],"src":[["ADM letter of 27 Feb 2026 (copy hosted by JAMMA)","https://www.jamma.it/wp-content/uploads/2026/02/ADMUC_137548_2026_841-proroga-13-11-26.pdf","o"],["JAMMA","https://www.jamma.it/primopiano/gioco-online-rinvio-al-13-novembre-2026-per-le-nuove-regole-tecniche-per-pvr-e-limiti-100-euro-obblighi-da-maggio-347509","p"]],"archive":true,"es":{"mkt":"Italia","auth":"ADM","t":"La ADM aplaza al 13 de noviembre el plazo del nuevo sistema de juego online","d":"La ADM indicó que a 23 de febrero se habían presentado muy pocas solicitudes de certificación. Varias obligaciones de protección del jugador siguen aplicándose desde el 13 de mayo.","b":["En una carta del 27 de febrero de 2026 a los concesionarios online, la dirección de juego de la ADM amplió el plazo para completar las verificaciones de conformidad con los organismos de verificación y obtener el certificado de la ADM para el nuevo sistema del concesionario. La nueva fecha es el 13 de noviembre de 2026, en lugar del 13 de mayo, y la ADM la calificó de definitiva.","La ADM señaló que a 23 de febrero habían llegado muy pocas solicitudes a los organismos de verificación, y que las consultas con esos organismos confirmaron que no se podía cumplir la fecha original. El aplazamiento afecta solo a los trámites técnicos de certificación.","Las obligaciones ya vigentes se mantienen, entre ellas un sitio .it propiedad del concesionario, la comprobación del documento de identidad y del código fiscal en el registro, los límites para las cuentas abiertas después del 13 de noviembre de 2025 y las nuevas normas de autoexclusión. Desde el 13 de mayo los concesionarios deben aplicar también la mayoría de las medidas de juego responsable del convenio de concesión y comunicar las recargas en efectivo en los puntos de venta, para que la ADM pueda hacer cumplir el límite semanal de 100 euros."]},"ru":{"mkt":"Италия","auth":"ADM","t":"ADM перенесло срок перехода на новую систему онлайн-игр на 13 ноября","d":"По данным ADM, к 23 февраля было подано очень мало заявок на сертификацию. Ряд обязанностей по защите игроков по-прежнему действует с 13 мая.","b":["В письме онлайн-концессионерам от 27 февраля 2026 года игорная дирекция итальянского Агентства таможни и монополий (ADM) продлила срок завершения проверок соответствия в органах по проверке и получения сертификата ADM для новой системы концессионера. Новым сроком стало 13 ноября 2026 года вместо 13 мая, и ADM назвало его окончательным.","По данным ADM, к 23 февраля в органы по проверке поступило очень мало заявок, а консультации с этими органами подтвердили, что первоначальный срок соблюсти невозможно. Перенос касается только этапов технической сертификации.","Действующие обязанности сохраняются, в том числе сайт в домене .it, принадлежащий концессионеру, проверка документа и налогового кода при регистрации, лимиты для счетов, открытых после 13 ноября 2025 года, и новые правила самоисключения. С 13 мая концессионеры также обязаны применять большинство мер ответственной игры, предусмотренных концессионным соглашением, и сообщать о пополнениях наличными в розничных точках, чтобы ADM могло контролировать соблюдение недельного лимита в 100 евро."]}}]);
